const $ = id => document.getElementById(id);
const fileInput = $('fileInput'), uploadArea = $('uploadArea'), workspace = $('workspace');
const fileList = $('fileList'), processBtn = $('processBtn'), downloadBtn = $('downloadBtn');
const quality = $('quality'), progBar = $('progBar'), progFill = $('progFill'), statusText = $('statusText');

let files = [], results = [];

// Upload
uploadArea.addEventListener('click', () => fileInput.click());
uploadArea.addEventListener('dragover', e => { e.preventDefault(); uploadArea.style.borderColor = '#4f46e5'; });
uploadArea.addEventListener('dragleave', () => { uploadArea.style.borderColor = '#d1d5db'; });
uploadArea.addEventListener('drop', e => {
  e.preventDefault(); uploadArea.style.borderColor = '#d1d5db';
  addFiles(Array.from(e.dataTransfer.files).filter(f => f.type.startsWith('image/')));
});
fileInput.addEventListener('change', () => { addFiles(Array.from(fileInput.files)); fileInput.value = ''; });

function addFiles(arr) {
  files = files.concat(arr);
  renderList();
  workspace.style.display = 'block';
  uploadArea.style.display = 'none';
}

function renderList() {
  fileList.innerHTML = '';
  files.forEach((f, i) => {
    const div = document.createElement('div');
    div.className = 'file-item';
    div.innerHTML = `<span>${i + 1}.</span><strong>${f.name}</strong><span>${(f.size / 1024).toFixed(1)} KB</span>`;
    fileList.appendChild(div);
  });
}

quality.addEventListener('input', () => $('qLabel').textContent = quality.value + '%');
$('wmOpacity').addEventListener('input', () => $('opLabel').textContent = $('wmOpacity').value + '%');

processBtn.addEventListener('click', processAll);

async function processAll() {
  if (!files.length) return;
  processBtn.disabled = true;
  downloadBtn.disabled = true;
  progBar.style.display = 'block';
  results = [];

  const fmt = $('outFmt').value;
  const q = quality.value / 100;
  const wmText = $('wmText').value;
  const wmSize = parseInt($('wmSize').value) || 24;
  const wmAlpha = parseInt($('wmOpacity').value) / 100;
  const tW = parseInt($('resizeW').value) || 0;
  const tH = parseInt($('resizeH').value) || 0;

  for (let i = 0; i < files.length; i++) {
    statusText.textContent = `Processing ${i + 1}/${files.length}: ${files[i].name}`;
    progFill.style.width = ((i / files.length) * 100) + '%';
    const blob = await processOne(files[i], tW, tH, fmt, q, wmText, wmSize, wmAlpha);
    results.push({ name: files[i].name, blob });
  }

  progFill.style.width = '100%';
  statusText.textContent = `Done! ${results.length} images processed.`;
  processBtn.disabled = false;
  downloadBtn.disabled = false;
}

function processOne(file, tW, tH, fmt, q, wmText, wmSize, wmAlpha) {
  return new Promise(resolve => {
    const reader = new FileReader();
    reader.onload = e => {
      const img = new Image();
      img.onload = () => {
        let w = img.width, h = img.height;
        if (tW && tH) { w = tW; h = tH; }
        else if (tW) { h = Math.round(img.height * tW / img.width); w = tW; }
        else if (tH) { w = Math.round(img.width * tH / img.height); h = tH; }

        const c = document.createElement('canvas');
        c.width = w; c.height = h;
        const ctx = c.getContext('2d');
        ctx.drawImage(img, 0, 0, w, h);

        if (wmText) {
          ctx.globalAlpha = wmAlpha;
          ctx.font = `${wmSize}px sans-serif`;
          ctx.fillStyle = '#000';
          ctx.fillText(wmText, 20, h - 20);
          ctx.globalAlpha = 1;
        }

        const outFmt = fmt === 'same' ? file.type || 'image/jpeg' : fmt;
        c.toBlob(blob => resolve(blob), outFmt, q);
      };
      img.src = e.target.result;
    };
    reader.readAsDataURL(file);
  });
}

downloadBtn.addEventListener('click', async () => {
  const zip = new JSZip();
  results.forEach((r, i) => {
    const name = r.name.replace(/\.[^.]+$/, '') + '.jpg';
    zip.file(name, r.blob);
  });
  const blob = await zip.generateAsync({ type: 'blob' });
  const a = document.createElement('a');
  a.download = 'processed-images.zip';
  a.href = URL.createObjectURL(blob);
  a.click();
});

$('clearBtn').addEventListener('click', () => {
  files = []; results = [];
  fileList.innerHTML = '';
  workspace.style.display = 'none';
  uploadArea.style.display = 'block';
  progBar.style.display = 'none';
  statusText.textContent = '';
});

