const $ = id => document.getElementById(id);
const fileInput = $('fileInput'), uploadArea = $('uploadArea'), workspace = $('workspace');
const canvas = $('canvas'), ctx = canvas.getContext('2d');
const sizeSlider = $('sizeSlider'), offX = $('offX'), offY = $('offY');
const bgType = $('bgType'), bgColor = $('bgColor');
let img = null, imgW = 0, imgH = 0;

uploadArea.addEventListener('click', () => fileInput.click());
uploadArea.addEventListener('dragover', e => { e.preventDefault(); uploadArea.style.borderColor = '#4f46e5'; });
uploadArea.addEventListener('dragleave', () => { uploadArea.style.borderColor = '#d1d5db'; });
uploadArea.addEventListener('drop', e => {
  e.preventDefault(); uploadArea.style.borderColor = '#d1d5db';
  if (e.dataTransfer.files.length) loadImg(e.dataTransfer.files[0]);
});
fileInput.addEventListener('change', () => { if (fileInput.files.length) loadImg(fileInput.files[0]); });

function loadImg(file) {
  const reader = new FileReader();
  reader.onload = e => {
    img = new Image();
    img.onload = () => {
      imgW = img.width; imgH = img.height;
      uploadArea.style.display = 'none'; workspace.style.display = 'block';
      render();
    };
    img.src = e.target.result;
  };
  reader.readAsDataURL(file);
}

function render() {
  const minSide = Math.min(imgW, imgH);
  const outSize = Math.max(minSide, 300);
  canvas.width = outSize; canvas.height = outSize;
  const scale = outSize / minSide;

  // background
  const bg = bgType.value;
  if (bg === 'white') { ctx.fillStyle = '#fff'; ctx.fillRect(0, 0, outSize, outSize); }
  else if (bg === 'custom') { ctx.fillStyle = bgColor.value; ctx.fillRect(0, 0, outSize, outSize); }
  else { ctx.clearRect(0, 0, outSize, outSize); }

  const pct = sizeSlider.value / 100;
  const radius = minSide * 0.5 * pct;
  const cx = minSide * 0.5 + (offX.value / 50) * (minSide * 0.5 - radius);
  const cy = minSide * 0.5 + (offY.value / 50) * (minSide * 0.5 - radius);

  ctx.save();
  ctx.scale(scale, scale);
  ctx.beginPath();
  ctx.arc(cx, cy, radius, 0, Math.PI * 2);
  ctx.closePath();
  ctx.clip();
  ctx.drawImage(img, 0, 0, imgW, imgH);
  ctx.restore();
}

['input','change'].forEach(evt => {
  sizeSlider.addEventListener(evt, () => { $('sizeLabel').textContent = sizeSlider.value + '%'; render(); });
  offX.addEventListener(evt, () => { $('offXLabel').textContent = offX.value; render(); });
  offY.addEventListener(evt, () => { $('offYLabel').textContent = offY.value; render(); });
  bgType.addEventListener(evt, () => {
    bgColor.style.display = bgType.value === 'custom' ? 'inline-block' : 'none';
    render();
  });
  bgColor.addEventListener(evt, render);
});

$('dlBtn').addEventListener('click', () => {
  const a = document.createElement('a');
  a.download = 'circle-crop.png';
  a.href = canvas.toDataURL('image/png');
  a.click();
});
$('resetBtn').addEventListener('click', () => {
  sizeSlider.value = 80; offX.value = 0; offY.value = 0;
  $('sizeLabel').textContent = '80%'; $('offXLabel').textContent = '0'; $('offYLabel').textContent = '0';
  render();
});
$('newBtn').addEventListener('click', () => { workspace.style.display = 'none'; uploadArea.style.display = 'block'; fileInput.value = ''; });

