tools.inline_js:
const $ = id => document.getElementById(id);
const fileInput = $('fileInput'), dropzone = $('dropzone'), workspace = $('workspace');
const previewList = $('previewList'), convertBtn = $('convertBtn'), downloadAllBtn = $('downloadAllBtn');
const addMoreBtn = $('addMoreBtn'), clearBtn = $('clearBtn');
const progBar = $('progBar'), progFill = $('progFill'), statusText = $('status');
const formatSelect = $('formatSelect');

let files = [];

setupDropzone({ dropzoneId: 'dropzone', inputId: 'fileInput', multiple: true, onFile: addFiles });

function addFiles(arr) {
  if (!arr || !arr.length) return;
  const images = Array.isArray(arr) ? arr : [arr];
  const valid = images.filter(f => f.type && f.type.startsWith('image/'));
  if (!valid.length) return alert('Please select valid image files.');
  files = files.concat(valid.map(f => ({ name: f.name, file: f, url: URL.createObjectURL(f), convertedUrl: null, convertedBlob: null })));
  dropzone.style.display = 'none';
  workspace.style.display = 'block';
  if (document.getElementById('beforeAfterPreview')) document.getElementById('beforeAfterPreview').classList.add('hidden');
  renderList();
}

function formatSize(bytes) {
  if (bytes < 1024) return bytes + ' B';
  if (bytes < 1024 * 1024) return (bytes / 1024).toFixed(1) + ' KB';
  return (bytes / (1024 * 1024)).toFixed(2) + ' MB';
}

function renderList() {
  previewList.innerHTML = '';
  files.forEach((item, i) => {
    const div = document.createElement('div');
    div.className = 'prev-item';
    const ext = formatSelect.value.split('/')[1];
    const outName = item.name.replace(/\.[^.]+$/, '') + '.' + ext;
    const info = item.convertedBlob
      ? '<p>✅ Converted: ' + formatSize(item.convertedBlob.size) + '</p>'
      : '<p>⏳ Waiting...</p>';
    const dl = item.convertedBlob
      ? '<a href="' + item.convertedUrl + '" download="' + outName + '" class="btn btn-secondary" style="padding:4px 10px;font-size:0.8rem;align-self:center">Download</a>'
      : '';
    div.innerHTML = '<img class="thumb" src="' + item.url + '"><div class="info"><p><strong>' + item.name + '</strong></p><p>Original: ' + formatSize(item.file.size) + '</p>' + info + '</div>' + dl + '<button title="Remove" style="align-self:flex-start">✕</button>';
    div.querySelector('button').addEventListener('click', function(e) {
      e.stopPropagation();
      URL.revokeObjectURL(item.url);
      if (item.convertedUrl) URL.revokeObjectURL(item.convertedUrl);
      files.splice(i, 1);
      renderList();
    });
    previewList.appendChild(div);
  });
  const converted = files.filter(function(f) { return f.convertedBlob; });
  downloadAllBtn.style.display = converted.length > 1 ? 'inline-block' : 'none';
}

addMoreBtn.addEventListener('click', function() { fileInput.click(); });

convertBtn.addEventListener('click', async function() {
  if (!files.length) return;
  convertBtn.disabled = true;
  progBar.style.display = 'block';
  const format = formatSelect.value;
  for (let i = 0; i < files.length; i++) {
    if (files[i].convertedUrl) { progFill.style.width = (((i + 1) / files.length) * 100) + '%'; continue; }
    statusText.textContent = 'Converting ' + (i+1) + '/' + files.length + ': ' + files[i].name + '...';
    progFill.style.width = ((i / files.length) * 100) + '%';
    try {
      const img = await ImageUtils.load(files[i].file);
      const canvas = ImageUtils.createCanvas(img.naturalWidth, img.naturalHeight);
      canvas.getContext('2d').drawImage(img, 0, 0);
      const blob = await ImageUtils.canvasToBlob(canvas, format, 0.92);
      files[i].convertedBlob = blob;
      files[i].convertedUrl = URL.createObjectURL(blob);
    } catch (err) {
      statusText.textContent = 'Error converting ' + files[i].name + ': ' + err.message;
      console.error(err);
    }
  }
  progFill.style.width = '100%';
  const totalOriginal = files.reduce(function(s, f) { return s + f.file.size; }, 0);
  const totalConverted = files.filter(function(f) { return f.convertedBlob; }).reduce(function(s, f) { return s + f.convertedBlob.size; }, 0);
  statusText.textContent = 'Done! ' + files.filter(function(f) { return f.convertedBlob; }).length + ' file(s) converted. Total: ' + formatSize(totalOriginal) + ' → ' + formatSize(totalConverted);
  setTimeout(function() { progBar.style.display = 'none'; statusText.textContent = ''; }, 4000);
  convertBtn.disabled = false;
  renderList();
});

downloadAllBtn.addEventListener('click', async function() {
  const format = formatSelect.value;
  const ext = format.split('/')[1];
  const zip = new JSZip();
  files.forEach(function(item) {
    if (item.convertedBlob) {
      const outName = item.name.replace(/\.[^.]+$/, '') + '.' + ext;
      zip.file(outName, item.convertedBlob);
    }
  });
  statusText.textContent = 'Creating ZIP...';
  const blob = await zip.generateAsync({ type: 'blob' });
  const a = document.createElement('a');
  a.download = 'converted-images.zip';
  a.href = URL.createObjectURL(blob);
  a.click();
  URL.revokeObjectURL(a.href);
  statusText.textContent = 'ZIP downloaded!';
  setTimeout(function() { statusText.textContent = ''; }, 2000);
});

clearBtn.addEventListener('click', function() {
  files.forEach(function(f) { URL.revokeObjectURL(f.url); if (f.convertedUrl) URL.revokeObjectURL(f.convertedUrl); });
  files = [];
  previewList.innerHTML = '';
  workspace.style.display = 'none'; dropzone.style.display = '';
  progBar.style.display = 'none'; statusText.textContent = '';
  if (document.getElementById('beforeAfterPreview')) document.getElementById('beforeAfterPreview').classList.remove('hidden');
});

(function() {
  var sampleBtn = document.getElementById('sampleBtn');
  if (sampleBtn) {
    sampleBtn.addEventListener('click', async function(e) {
      e.stopPropagation(); e.preventDefault();
      sampleBtn.textContent = '⏳ Loading...';
      try {
        const resp = await fetch('https://images.unsplash.com/photo-1469474968028-56623f02e42e?w=800&q=80');
        const blob = await resp.blob();
