let originalImage = null;
let detectedFaces = [];
let blurMode = 'blur';
let canvas = document.getElementById('previewCanvas');
let ctx = canvas.getContext('2d');

const dropzone = document.getElementById('dropzone');
const fileInput = document.getElementById('fileInput');
const detectBtn = document.getElementById('detectBtn');
const applyBtn = document.getElementById('applyBtn');
const downloadBtn = document.getElementById('downloadBtn');
const resetBtn = document.getElementById('resetBtn');
const modeSel = document.getElementById('modeSel');

dropzone.addEventListener('dragover', e => { e.preventDefault(); dropzone.style.borderColor = 'var(--accent)'; });
dropzone.addEventListener('dragleave', () => { dropzone.style.borderColor = 'var(--border-color)'; });
dropzone.addEventListener('drop', e => {
  e.preventDefault();
  dropzone.style.borderColor = 'var(--border-color)';
  if (e.dataTransfer.files.length > 0) {
    handleFile(e.dataTransfer.files[0]);
  }
});
fileInput.addEventListener('change', e => { if (e.target.files[0]) handleFile(e.target.files[0]); });

function handleFile(file) {
  if (!file || !file.type.startsWith('image/')) {
    alert('Please select an image file.');
    return;
  }
  const url = URL.createObjectURL(file);
  originalImage = new Image();
  originalImage.onload = () => {
    canvas.width = originalImage.width;
    canvas.height = originalImage.height;
    ctx.drawImage(originalImage, 0, 0);
    dropzone.style.display = 'none';
    document.getElementById('workspace').style.display = 'block';
  };
  originalImage.src = url;
}

function applyBlurToFaces() {
  if (!originalImage || !detectedFaces.length) return;
  detectedFaces.forEach(face => {
    ctx.save();
    if (blurMode === 'pixelate') {
      const off = document.createElement('canvas');
      const s = 8;
      off.width = s; off.height = s;
      off.getContext('2d').drawImage(canvas, face.x, face.y, face.w, face.h, 0, 0, s, s);
      ctx.imageSmoothingEnabled = false;
      ctx.drawImage(off, 0, 0, s, s, face.x, face.y, face.w, face.h);
      ctx.imageSmoothingEnabled = true;
    } else {
      ctx.filter = 'blur(15px)';
      ctx.drawImage(canvas, face.x, face.y, face.w, face.h, face.x, face.y, face.w, face.h);
      ctx.filter = 'none';
    }
    ctx.restore();
  });
}

applyBtn && applyBtn.addEventListener('click', applyBlurToFaces);
downloadBtn && downloadBtn.addEventListener('click', () => {
  canvas.toBlob(blob => {
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = 'blurred.png';
    a.click();
    URL.revokeObjectURL(url);
  });
});
resetBtn && resetBtn.addEventListener('click', () => {
  originalImage = null;
  detectedFaces = [];
  document.getElementById('workspace').style.display = 'none';
  dropzone.style.display = '';
  fileInput.value = '';
});

