const SIZES = [16, 32, 48, 64, 128, 256, 512];
const $ = id => document.getElementById(id);
const fileInput = $('fileInput'), uploadArea = $('uploadArea'), workspace = $('workspace');
let img = null, canvases = {};

uploadArea.addEventListener('click', () => fileInput.click());
uploadArea.addEventListener('dragover', e => { e.preventDefault(); uploadArea.style.borderColor = '#4f46e5'; });
uploadArea.addEventListener('dragleave', () => { uploadArea.style.borderColor = '#d1d5db'; });
uploadArea.addEventListener('drop', e => {
  e.preventDefault(); uploadArea.style.borderColor = '#d1d5db';
  if (e.dataTransfer.files.length) loadImg(e.dataTransfer.files[0]);
});
fileInput.addEventListener('change', () => { if (fileInput.files.length) loadImg(fileInput.files[0]); });

function loadImg(file) {
  const reader = new FileReader();
  reader.onload = e => {
    img = new Image();
    img.onload = () => { uploadArea.style.display = 'none'; workspace.style.display = 'block'; generate(); };
    img.src = e.target.result;
  };
  reader.readAsDataURL(file);
}

function generate() {
  const wrap = $('previewWrap'); wrap.innerHTML = '';
  canvases = {};
  SIZES.forEach(s => {
    const c = document.createElement('canvas'); c.width = s; c.height = s;
    const ctx = c.getContext('2d');
    ctx.clearRect(0, 0, s, s);
    ctx.drawImage(img, 0, 0, img.width, img.height, 0, 0, s, s);
    canvases[s] = c;

    const div = document.createElement('div');
    div.className = 'fav-preview';
    div.appendChild(c);
    const lb = document.createElement('span');
    lb.textContent = s + '×' + s;
    div.appendChild(lb);
    wrap.appendChild(div);
  });
  buildSnippets();
}

function buildSnippets() {
  const lines = SIZES.map(s => {
    const rel = s === 512 ? 'apple-touch-icon' : 'icon';
    const sz = s === 512 ? '' : ` sizes="${s}x${s}"`;
    const mime = s <= 48 ? 'image/x-icon' : 'image/png';
    return `<link rel="${rel}" href="/favicon-${s}.png"${sz}>`;
  });
  lines.push(`<link rel="shortcut icon" href="/favicon-32.png">`);
  $('htmlSnippet').textContent = lines.join('\n');

  const manifest = {
    name: "My App",
    short_name: "MyApp",
    icons: SIZES.map(s => ({ src: `/favicon-${s}.png`, sizes: `${s}x${s}`, type: s <= 48 ? 'image/x-icon' : 'image/png' }))
  };
  $('manifestBlock').textContent = JSON.stringify(manifest, null, 2);
}

$('dlZipBtn').addEventListener('click', async () => {
  const zip = new JSZip();
  SIZES.forEach(s => {
    zip.file(`favicon-${s}.png`, canvases[s].toDataURL('image/png').split(',')[1], { base64: true });
  });
  // ICO: use 16,32,48 as PNG-embedded ICO (modern browsers support PNG-in-ICO)
  const icoBlob = makeICO([16, 32, 48].map(s => canvases[s]));
  zip.file('favicon.ico', icoBlob);
  zip.file('html-snippet.txt', $('htmlSnippet').textContent);
  zip.file('manifest.json', $('manifestBlock').textContent);
  const blob = await zip.generateAsync({ type: 'blob' });
  const a = document.createElement('a');
  a.download = 'favicons.zip'; a.href = URL.createObjectURL(blob); a.click();
});

function makeICO(canvasArr) {
  // Minimal ICO: header(6) + entries(16 each) + PNG data
  const pngDatas = canvasArr.map(c => {
    const d = c.toDataURL('image/png').split(',')[1];
    return Uint8Array.from(atob(d), c => c.charCodeAt(0));
  });
  const header = new Uint8Array(6);
  header[0] = 0; header[1] = 0; // reserved
  header[2] = 1; header[3] = 0; // type=1 (ICO)
  header[4] = pngDatas.length & 0xff; header[5] = (pngDatas.length >> 8) & 0xff;
  let entriesLen = pngDatas.length * 16;
  let totalLen = 6 + entriesLen + pngDatas.reduce((a, b) => a + b.length, 0);
  const out = new Uint8Array(totalLen);
  out.set(header, 0);
  let dataOffset = 6 + entriesLen;
  pngDatas.forEach((png, i) => {
    const s = canvasArr[i].width;
    const off = 6 + i * 16;
    out[off] = s >= 256 ? 0 : s; // width (0=256)
    out[off+1] = s >= 256 ? 0 : s; // height
    out[off+2] = 0; // palette
    out[off+3] = 0; // reserved
    out[off+4] = 1; out[off+5] = 0; // color planes
    out[off+6] = 32; out[off+7] = 0; // bits per pixel
    const sz = png.length;
    out[off+8] = sz & 0xff; out[off+9] = (sz>>8)&0xff; out[off+10] = (sz>>16)&0xff; out[off+11] = (sz>>24)&0xff;
    out[off+12] = dataOffset & 0xff; out[off+13] = (dataOffset>>8)&0xff; out[off+14] = (dataOffset>>16)&0xff; out[off+15] = (dataOffset>>24)&0xff;
    out.set(png, dataOffset);
    dataOffset += sz;
  });
  return out;
}

$('copyHtmlBtn').addEventListener('click', () => navigator.clipboard.writeText($('htmlSnippet').textContent));
$('copyManifestBtn').addEventListener('click', () => navigator.clipboard.writeText($('manifestBlock').textContent));
