tools.inline_js:
const $ = id => document.getElementById(id);
const fileInput = $('fileInput'), uploadArea = $('uploadArea'), workspace = $('workspace');
const previewList = $('previewList'), convertBtn = $('convertBtn'), downloadAllBtn = $('downloadAllBtn');
const addMoreBtn = $('addMoreBtn'), clearBtn = $('clearBtn');
const progBar = $('progBar'), progFill = $('progFill'), statusText = $('statusText');
const outputFormat = $('outputFormat'), jpgQuality = $('jpgQuality');

let files = []; // { name, blob, url, convertedUrl, convertedBlob }
let convertedCount = 0;

// Upload
uploadArea.addEventListener('click', () => fileInput.click());
uploadArea.addEventListener('dragover', e => { e.preventDefault(); uploadArea.style.borderColor = '#4f46e5'; });
uploadArea.addEventListener('dragleave', () => { uploadArea.style.borderColor = '#d1d5db'; });
uploadArea.addEventListener('drop', e => {
  e.preventDefault(); uploadArea.style.borderColor = '#d1d5db';
  addFiles(Array.from(e.dataTransfer.files).filter(f =>
    f.name.toLowerCase().endsWith('.heic') || f.name.toLowerCase().endsWith('.heif') || f.type === 'image/heic' || f.type === 'image/heif'
  ));
});
fileInput.addEventListener('change', () => {
  addFiles(Array.from(fileInput.files).filter(f =>
    f.name.toLowerCase().endsWith('.heic') || f.name.toLowerCase().endsWith('.heif') || f.type === 'image/heic' || f.type === 'image/heif'
  ));
  fileInput.value = '';
});

function addFiles(arr) {
  if (!arr.length) return alert('Please select valid HEIC/HEIF files.');
  files = files.concat(arr.map(f => ({ name: f.name, blob: f, url: URL.createObjectURL(f), convertedUrl: null, convertedBlob: null })));
  uploadArea.style.display = 'none';
  workspace.style.display = 'block';
  renderList();
}

function renderList() {
  previewList.innerHTML = '';
  files.forEach((item, i) => {
    const div = document.createElement('div');
    div.className = 'prev-item';
    const ext = outputFormat.value === 'image/jpeg' ? '.jpg' : '.png';
    const outName = item.name.replace(/\.(heic|heif)$/i, '') + ext;
    div.innerHTML = `
      <span style="width:2rem;color:#9ca3af">${i+1}</span>
      <span style="font-size:0.85rem;color:#6b7280;min-width:80px">${item.name}</span>
      <span style="flex:1">${item.convertedUrl ? '✅ ' + outName : '⏳ waiting...'}</span>
      ${item.convertedUrl ? `<a href="${item.convertedUrl}" download="${outName}" style="margin-right:8px" class="btn btn-secondary" style="padding:4px 10px;font-size:0.8rem">Download</a>` : ''}
      <button title="Remove">✕</button>`;
    div.querySelector('button').addEventListener('click', e => { e.stopPropagation(); URL.revokeObjectURL(item.url); if (item.convertedUrl) URL.revokeObjectURL(item.convertedUrl); files.splice(i, 1); renderList(); });
    previewList.appendChild(div);
  });
  downloadAllBtn.style.display = convertedCount > 1 ? 'inline-block' : 'none';
}

addMoreBtn.addEventListener('click', () => fileInput.click());

convertBtn.addEventListener('click', async () => {
  if (!files.length) return;
  convertBtn.disabled = true;
  progBar.style.display = 'block';
  const fmt = outputFormat.value;
  const ext = fmt === 'image/jpeg' ? '.jpg' : '.png';

  for (let i = 0; i < files.length; i++) {
    if (files[i].convertedUrl) { // already converted
      progFill.style.width = (((i + 1) / files.length) * 100) + '%';
      continue;
    }
    statusText.textContent = `Converting ${i+1}/${files.length}: ${files[i].name}...`;
    progFill.style.width = ((i / files.length) * 100) + '%';

    try {
      // heic2any returns a Blob (or array of Blobs for GIF)
      const convertedBlob = await heic2any({ blob: files[i].blob, toType: fmt });
      const blob = Array.isArray(convertedBlob) ? convertedBlob[0] : convertedBlob;
      files[i].convertedBlob = blob;
      files[i].convertedUrl = URL.createObjectURL(blob);
      convertedCount++;
    } catch (err) {
      statusText.textContent = `Error converting ${files[i].name}: ${err.message}`;
      console.error(err);
    }
  }

  progFill.style.width = '100%';
  statusText.textContent = `Done! ${convertedCount} file(s) converted.`;
  setTimeout(() => { progBar.style.display = 'none'; statusText.textContent = ''; }, 3000);
  convertBtn.disabled = false;
  renderList();
});

downloadAllBtn.addEventListener('click', async () => {
  const fmt = outputFormat.value;
  const ext = fmt === 'image/jpeg' ? '.jpg' : '.png';
  const zip = new JSZip();
  files.forEach((item, i) => {
    if (item.convertedBlob) {
      const outName = item.name.replace(/\.(heic|heif)$/i, '') + ext;
      zip.file(outName, item.convertedBlob);
    }
  });
  statusText.textContent = 'Creating ZIP...';
  const blob = await zip.generateAsync({ type: 'blob' });
  const a = document.createElement('a');
  a.download = 'converted-images.zip';
  a.href = URL.createObjectURL(blob);
  a.click();
  URL.revokeObjectURL(a.href);
  statusText.textContent = 'ZIP downloaded!';
  setTimeout(() => { statusText.textContent = ''; }, 2000);
});

clearBtn.addEventListener('click', () => {
  files.forEach(f => { URL.revokeObjectURL(f.url); if (f.convertedUrl) URL.revokeObjectURL(f.convertedUrl); });
  files = []; convertedCount = 0;
  previewList.innerHTML = '';
  workspace.style.display = 'none'; uploadArea.style.display = 'block';
  progBar.style.display = 'none'; statusText.textContent = '';
});

