'use strict';

const ALL_SIZES = [16, 24, 32, 48, 64, 96, 128, 256, 512];
const state = {
  sourceImg: null,
  sourceW: 0, sourceH: 0,
  selected: new Set([16, 32, 48, 64, 128, 256]),
  algo: 'high',
  corner: 0,
  bgMode: 'transparent',
  bgColor: '#6366f1',
  padding: 0,
};

const sizeGrid = document.getElementById('sizeGrid');
ALL_SIZES.forEach(sz => {
  const label = document.createElement('label');
  label.className = 'size-chip' + (state.selected.has(sz) ? ' checked' : '');
  label.innerHTML = `<input type="checkbox" value="${sz}" ${state.selected.has(sz) ? 'checked' : ''}><span>${sz} \u00d7 ${sz}</span>`;
  label.querySelector('input').addEventListener('change', e => {
    if (e.target.checked) state.selected.add(sz);
    else state.selected.delete(sz);
    label.classList.toggle('checked', e.target.checked);
  });
  sizeGrid.appendChild(label);
});

const dropzone = document.getElementById('dropzone');
const fileInput = document.getElementById('fileInput');
const algoSel = document.getElementById('algoSel');
const cornerSel = document.getElementById('cornerSel');
const bgSel = document.getElementById('bgSel');
const bgColor = document.getElementById('bgColor');
const paddingSel = document.getElementById('paddingSel');
const generateBtn = document.getElementById('generateBtn');
const downloadBtn = document.getElementById('downloadBtn');
const resetBtn = document.getElementById('resetBtn');

dropzone.addEventListener('dragover', e => { e.preventDefault(); dropzone.classList.add('drag'); });
dropzone.addEventListener('dragleave', () => { dropzone.classList.remove('drag'); });
dropzone.addEventListener('drop', e => {
  e.preventDefault();
  dropzone.classList.remove('drag');
  if (e.dataTransfer.files[0]) handleFile(e.dataTransfer.files[0]);
});
fileInput.addEventListener('change', e => { if (e.target.files[0]) handleFile(e.target.files[0]); });

function handleFile(file) {
  if (!file || !file.type.startsWith('image/')) {
    alert('Please select an image file.');
    return;
  }
  const url = URL.createObjectURL(file);
  state.sourceImg = new Image();
  state.sourceImg.onload = () => {
    state.sourceW = state.sourceImg.width;
    state.sourceH = state.sourceImg.height;
    dropzone.style.display = 'none';
    document.getElementById('workspace').style.display = 'block';
  };
  state.sourceImg.src = url;
}

function makeIcoAt(size) {
  const c = document.createElement('canvas');
  c.width = size; c.height = size;
  const cx = c.getContext('2d');
  if (state.bgMode === 'color') {
    cx.fillStyle = state.bgColor;
    cx.fillRect(0, 0, size, size);
  }
  const pad = Math.floor(size * (state.padding / 100));
  const iw = size - pad * 2;
  cx.drawImage(state.sourceImg, pad, pad, iw, iw);
  return new Promise(resolve => c.toBlob(resolve, 'image/png'));
}

generateBtn && generateBtn.addEventListener('click', async () => {
  if (!state.sourceImg) return;
  generateBtn.disabled = true;
  const sizes = Array.from(state.selected).sort((a,b) => a-b);
  const blobs = await Promise.all(sizes.map(makeIcoAt));
  const headerSize = 6 + 16 * blobs.length;
  let offset = headerSize;
  const parts = [];
  parts.push(new Uint8Array([0,0,1,0, blobs.length & 0xff, (blobs.length>>8) & 0xff]));
  blobs.forEach((b, i) => {
    const sz = sizes[i];
    const w = sz >= 256 ? 0 : sz;
    const h = sz >= 256 ? 0 : sz;
    const bArr = new Uint8Array(b);
    parts.push(new Uint8Array([
      w, h, 0, 0, 1, 0, 32, 0,
      bArr.length & 0xff, (bArr.length>>8) & 0xff, (bArr.length>>16) & 0xff, (bArr.length>>24) & 0xff,
      offset & 0xff, (offset>>8) & 0xff, (offset>>16) & 0xff, (offset>>24) & 0xff
    ]));
    offset += bArr.length;
  });
  blobs.forEach(b => parts.push(new Uint8Array(b)));
  const icoFile = new Blob(parts, { type: 'image/x-icon' });
  const url = URL.createObjectURL(icoFile);
  document.getElementById('resultArea').innerHTML = '<a href="' + url + '" download="icon.ico">Download ICO</a>';
  generateBtn.disabled = false;
});

resetBtn && resetBtn.addEventListener('click', () => {
  state.sourceImg = null;
  document.getElementById('workspace').style.display = 'none';
  dropzone.style.display = '';
  fileInput.value = '';
});

