const dropzone = document.getElementById('dropzone');
    const fileInput = document.getElementById('fileInput');
    const previewArea = document.getElementById('previewArea');
    const resultImg = document.getElementById('resultImg');
    const brightnessRange = document.getElementById('brightnessRange');
    const contrastRange = document.getElementById('contrastRange');
    const saturationRange = document.getElementById('saturationRange');
    const brightnessVal = document.getElementById('brightnessVal');
    const contrastVal = document.getElementById('contrastVal');
    const saturationVal = document.getElementById('saturationVal');
    const applyBtn = document.getElementById('applyBtn');
    const downloadBtn = document.getElementById('downloadBtn');
    const resetBtn = document.getElementById('resetBtn');
    const status = document.getElementById('status');

    let currentFile = null;
    let originalImg = null;
    let resultBlob = null;
    let prevBlobUrl = null;

    setupDropzone({ dropzoneId: 'dropzone', inputId: 'fileInput', onFile: handleFile });

    brightnessRange.addEventListener('input', () => { brightnessVal.textContent = brightnessRange.value + '%'; });
    contrastRange.addEventListener('input', () => { contrastVal.textContent = contrastRange.value + '%'; });
    saturationRange.addEventListener('input', () => { saturationVal.textContent = saturationRange.value + '%'; });

    function handleFile(file) {
      if (!file.type.startsWith('image/')) { status.textContent = 'Please select an image file.'; return; }
      currentFile = file;
      ImageUtils.load(file).then(async img => {
        originalImg = img;
        status.innerHTML = '<div class="spinner"></div>';
        try {
          await applyAdjustment();
        } catch(e) {
          status.textContent = 'Error: ' + e.message;
          return;
        }
        previewArea.classList.add('active');
        const bp = document.getElementById('beforeAfterPreview');
        if (bp) bp.classList.add('hidden');
        dropzone.classList.add('hidden');
        status.textContent = '';
        downloadBtn.classList.remove('hidden');
      }).catch(err => {
        status.textContent = 'Error loading image: ' + err.message;
      });
    }

    async function applyAdjustment() {
      if (!originalImg) return;
      const canvas = ImageUtils.createCanvas(originalImg.naturalWidth, originalImg.naturalHeight);
      const ctx = canvas.getContext('2d');
      const b = parseFloat(brightnessRange.value) / 100;
      const c = parseFloat(contrastRange.value) / 100;
      const s = parseFloat(saturationRange.value) / 100;
      ctx.filter = 'brightness(' + b + ') contrast(' + c + ') saturate(' + s + ')';
      ctx.drawImage(originalImg, 0, 0);
      const blob = await ImageUtils.canvasToBlob(canvas, 'image/jpeg', 0.92);
      // Revoke previous blob URL to avoid memory leak
      if (prevBlobUrl) { try { URL.revokeObjectURL(prevBlobUrl); } catch(e) {} }
      const url = URL.createObjectURL(blob);
      prevBlobUrl = url;
      resultBlob = blob;
      resultImg.src = url;
      return blob;
    }

    applyBtn.addEventListener('click', async function() {
      if (!originalImg) return;
      applyBtn.disabled = true;
      applyBtn.textContent = '🔄 Applying...';
      status.innerHTML = '<div class="spinner"></div>';
      try {
        await applyAdjustment();
        status.textContent = 'Done! Click Download to save.';
      } catch (err) {
        status.textContent = 'Error: ' + err.message;
      } finally {
        applyBtn.disabled = false;
        applyBtn.textContent = '✨ Apply Adjustments';
      }
    });

    downloadBtn.addEventListener('click', function() {
      if (resultBlob) {
        var base = (currentFile.name || 'image').replace(/\.[^.]+$/, '');
        ImageUtils.download(resultBlob, base + '-adjusted.jpg');
        try { SmartImgNextStep.show(); } catch(e) {}
      }
    });

    resetBtn.addEventListener('click', function() {
      if (prevBlobUrl) { try { URL.revokeObjectURL(prevBlobUrl); } catch(e) {} }
      prevBlobUrl = null;
      currentFile = null;
      originalImg = null;
      resultBlob = null;
      previewArea.classList.remove('active');
      var bp = document.getElementById('beforeAfterPreview');
      if (bp) bp.classList.remove('hidden');
      dropzone.classList.remove('hidden');
      fileInput.value = '';
      status.textContent = '';
      downloadBtn.classList.add('hidden');
      resultImg.src = '';
      brightnessRange.value = 100;
      contrastRange.value = 100;
      saturationRange.value = 100;
      brightnessVal.textContent = '100%';
      contrastVal.textContent = '100%';
      saturationVal.textContent = '100%';
    });

    // Sample image & Next Step
    (function() {
      var _handleFile = typeof handleFile === 'function' ? handleFile : null;
      if (_handleFile) {
        window.initSampleButton('https://images.unsplash.com/photo-1506744038136-46273834b3fb?w=800&q=80', _handleFile);
      }
    })();

