tools.inline_js:
const $ = id => document.getElementById(id);
const fileInput = $('fileInput'), uploadArea = $('uploadArea'), workspace = $('workspace');
const previewList = $('previewList'), compressBtn = $('compressBtn'), downloadAllBtn = $('downloadAllBtn');
const addMoreBtn = $('addMoreBtn'), clearBtn = $('clearBtn');
const progBar = $('progBar'), progFill = $('progFill'), statusText = $('statusText');
const qualityRange = $('qualityRange'), qualityVal = $('qualityVal'), maxWidth = $('maxWidth'), outputFmt = $('outputFmt');

let images = []; // { name, file, url, compressedUrl, compressedBlob, originalSize, compressedSize }

qualityRange.addEventListener('input', () => { qualityVal.textContent = qualityRange.value; });

// Upload
uploadArea.addEventListener('click', () => fileInput.click());
uploadArea.addEventListener('dragover', e => { e.preventDefault(); uploadArea.style.borderColor = '#4f46e5'; });
uploadArea.addEventListener('dragleave', () => { uploadArea.style.borderColor = '#d1d5db'; });
uploadArea.addEventListener('drop', e => {
  e.preventDefault(); uploadArea.style.borderColor = '#d1d5db';
  addFiles(Array.from(e.dataTransfer.files).filter(f => f.type.startsWith('image/')));
});
fileInput.addEventListener('change', () => { addFiles(Array.from(fileInput.files).filter(f => f.type.startsWith('image/'))); fileInput.value = ''; });

function addFiles(arr) {
  if (!arr.length) return;
  images = images.concat(arr.map(f => ({ name: f.name, file: f, url: URL.createObjectURL(f), compressedUrl: null, compressedBlob: null, originalSize: f.size, compressedSize: 0 })));
  uploadArea.style.display = 'none';
  workspace.style.display = 'block';
  renderList();
}

function formatSize(bytes) {
  if (bytes < 1024) return bytes + ' B';
  if (bytes < 1024 * 1024) return (bytes / 1024).toFixed(1) + ' KB';
  return (bytes / (1024 * 1024)).toFixed(2) + ' MB';
}

function renderList() {
  previewList.innerHTML = '';
  images.forEach((item, i) => {
    const div = document.createElement('div');
    div.className = 'prev-item';
    const hasCompressed = item.compressedUrl;
    const pct = hasCompressed && item.originalSize > 0 ? Math.round((1 - item.compressedSize / item.originalSize) * 100) : 0;
    const badge = hasCompressed ? (pct > 0 ? `<span class="badge badge-saved">-${pct}%</span>` : `<span class="badge badge-larger">+${Math.abs(pct)}%</span>`) : '';
    const fmt = outputFmt.value === 'same' ? item.file.type : outputFmt.value;
    const ext = fmt === 'image/png' ? '.png' : fmt === 'image/webp' ? '.webp' : '.jpg';
    const outName = item.name.replace(/\.(jpg|jpeg|png|webp)$/i, '') + (hasCompressed ? ext : '');

    div.innerHTML = `
      <img class="thumb" src="${item.url}">
      <div class="info">
        <p><strong>${item.name}</strong> ${badge}</p>
        <p>Original: ${formatSize(item.originalSize)}</p>
        ${hasCompressed ? `<p>Compressed: ${formatSize(item.compressedSize)}</p>` : '<p>Not compressed yet</p>'}
      </div>
      ${hasCompressed ? `<a href="${item.compressedUrl}" download="${outName}" class="btn btn-secondary" style="padding:4px 10px;font-size:0.8rem;align-self:center">Download</a>` : ''}
      <button title="Remove" style="align-self:flex-start">✕</button>`;
    div.querySelector('button').addEventListener('click', e => { e.stopPropagation(); URL.revokeObjectURL(item.url); if (item.compressedUrl) URL.revokeObjectURL(item.compressedUrl); images.splice(i, 1); renderList(); });
    previewList.appendChild(div);
  });
  downloadAllBtn.style.display = images.some(i => i.compressedUrl) && images.filter(i => i.compressedUrl).length > 1 ? 'inline-block' : 'none';
}

addMoreBtn.addEventListener('click', () => fileInput.click());

compressBtn.addEventListener('click', async () => {
  if (!images.length) return;
  compressBtn.disabled = true;
  progBar.style.display = 'block';

  const quality = parseInt(qualityRange.value) / 100;
  const maxW = parseInt(maxWidth.value) || undefined;

  for (let i = 0; i < images.length; i++) {
    if (images[i].compressedUrl) { // already compressed
      progFill.style.width = (((i + 1) / images.length) * 100) + '%';
      continue;
    }
    statusText.textContent = `Compressing ${i+1}/${images.length}: ${images[i].name}...`;
    progFill.style.width = ((i / images.length) * 100) + '%';

    try {
      const options = {
        maxSizeMB: Infinity, // we control via quality
        initialQuality: quality,
        useWebWorker: true,
        onProgress: p => { progFill.style.width = ((i + p) / images.length * 100) + '%'; }
      };
      if (maxW) options.maxWidthOrHeight = maxW;

      // browser-image-compression expects a File object
      let fileToCompress = images[i].file;
      // If output format differs, we need to re-encode — the library handles this via `fileType` option
      if (outputFmt.value !== 'same') options.fileType = outputFmt.value;

      const compressedFile = await imageCompression(fileToCompress, options);
      images[i].compressedBlob = compressedFile;
      images[i].compressedSize = compressedFile.size;
      images[i].compressedUrl = URL.createObjectURL(compressedFile);
    } catch (err) {
      statusText.textContent = `Error compressing ${images[i].name}: ${err.message}`;
      console.error(err);
    }
  }

  progFill.style.width = '100%';
  const totalOriginal = images.reduce((s, i) => s + i.originalSize, 0);
  const totalCompressed = images.filter(i => i.compressedUrl).reduce((s, i) => s + i.compressedSize, 0);
  statusText.textContent = `Done! Total saved: ${formatSize(totalOriginal)} → ${formatSize(totalCompressed)}`;
  setTimeout(() => { progBar.style.display = 'none'; statusText.textContent = ''; }, 4000);
  compressBtn.disabled = false;
  renderList();
});

downloadAllBtn.addEventListener('click', async () => {
  const zip = new JSZip();
  images.forEach(item => {
    if (item.compressedBlob) {
      const fmt = outputFmt.value === 'same' ? item.file.type : outputFmt.value;
      const ext = fmt === 'image/png' ? '.png' : fmt === 'image/webp' ? '.webp' : '.jpg';
      const outName = item.name.replace(/\.(jpg|jpeg|png|webp)$/i, '') + ext;
      zip.file(outName, item.compressedBlob);
    }
  });
  statusText.textContent = 'Creating ZIP...';
  const blob = await zip.generateAsync({ type: 'blob' });
  const a = document.createElement('a');
  a.download = 'compressed-images.zip';
  a.href = URL.createObjectURL(blob);
  a.click();
  URL.revokeObjectURL(a.href);
  statusText.textContent = 'ZIP downloaded!';
  setTimeout(() => { statusText.textContent = ''; }, 2000);
});

clearBtn.addEventListener('click', () => {
  images.forEach(f => { URL.revokeObjectURL(f.url); if (f.compressedUrl) URL.revokeObjectURL(f.compressedUrl); });
  images = [];
  previewList.innerHTML = '';
  workspace.style.display = 'none'; uploadArea.style.display = 'block';
  progBar.style.display = 'none'; statusText.textContent = '';
});

