const dropzone = document.getElementById('dropzone');
    const fileInput = document.getElementById('fileInput');
    const previewArea = document.getElementById('previewArea');
    const resultImg = document.getElementById('resultImg');
    const exifStatus = document.getElementById('exifStatus');
    const exifInfo = document.getElementById('exifInfo');
    const applyBtn = document.getElementById('applyBtn');
    const downloadBtn = document.getElementById('downloadBtn');
    const resetBtn = document.getElementById('resetBtn');
    const status = document.getElementById('status');

    let currentFile = null;
    let originalImg = null;
    let resultBlob = null;
    let prevBlobUrl = null;

    setupDropzone({ dropzoneId: 'dropzone', inputId: 'fileInput', onFile: handleFile });

    // Simple EXIF detection for JPEG files
    async function detectExif(file) {
      if (!file.type.includes('jpeg') && !file.name.match(/\.jpe?g$/i)) {
        return { hasExif: false, info: 'Not a JPEG file — no EXIF data possible.' };
      }
      try {
        const buf = await file.arrayBuffer();
        const view = new DataView(buf);
        if (view.getUint16(0) !== 0xFFD8) {
          return { hasExif: false, info: 'Not a valid JPEG file.' };
        }
        let offset = 2;
        let exifFound = false;
        let gpsFound = false;
        const tags = [];
        while (offset < buf.byteLength - 1) {
          if (view.getUint8(offset) !== 0xFF) break;
          const marker = view.getUint8(offset + 1);
          if (marker === 0xE1) { // APP1 — EXIF
            exifFound = true;
            const len = view.getUint16(offset + 2);
            const exifStart = offset + 4;
            const exifHeader = String.fromCharCode(...new Uint8Array(buf, exifStart, 6));
            if (exifHeader.includes('Exif')) {
              tags.push('EXIF block detected');
              // Try to read some EXIF tags
              try {
                const exifBuf = new Uint8Array(buf, exifStart, len - 2);
                const tagInfo = parseBasicExif(exifBuf);
                if (tagInfo.gps) gpsFound = true;
                tags.push(...tagInfo.tags);
              } catch(e) {}
            }
          }
          if (marker === 0xDA) break; // SOS — image data starts
          const segLen = view.getUint16(offset + 2);
          offset += 2 + segLen;
        }
        if (!exifFound) {
          return { hasExif: false, info: 'No EXIF data found in this image.' };
        }
        let msg = '<span class="exif-warn">⚠️ EXIF metadata detected:</span><br>';
        tags.forEach(t => { msg += '• ' + t + '<br>'; });
        if (gpsFound) msg += '<br><span class="exif-warn">⚠️ GPS location data found — remove it to protect your privacy!</span>';
        return { hasExif: true, info: msg };
      } catch(e) {
        return { hasExif: false, info: 'Could not read file metadata.' };
      }
    }

    function parseBasicExif(buf) {
      const tags = [];
      let gps = false;
      try {
        // Very basic: look for ASCII strings in EXIF data
        const str = String.fromCharCode(...buf);
        if (str.includes('GPS')) { gps = true; tags.push('GPS location data'); }
        if (str.match(/[A-Za-z]{3,}/)) { tags.push('Camera/software info present'); }
      } catch(e) {}
      return { tags, gps };
    }

    async function handleFile(file) {
      if (!file.type.startsWith('image/')) { status.textContent = 'Please select an image file.'; return; }
      currentFile = file;
      ImageUtils.load(file).then(async img => {
        originalImg = img;
        status.innerHTML = '<div class="spinner"></div> Checking metadata...';
        const exif = await detectExif(file);
        if (exif.hasExif) {
          exifInfo.innerHTML = exif.info;
          exifStatus.style.display = 'block';
        } else {
          exifInfo.innerHTML = '<span class="exif-clear">✅ No EXIF metadata detected. Your image is already clean.</span>';
          exifStatus.style.display = 'block';
        }
        previewArea.classList.add('active');
        const bp = document.getElementById('beforeAfterPreview');
        if (bp) bp.classList.add('hidden');
        dropzone.classList.add('hidden');
        status.textContent = 'Click "Remove EXIF" to strip metadata.';
        downloadBtn.classList.add('hidden');
      }).catch(err => {
        status.textContent = 'Error loading image: ' + err.message;
      });
    }

    async function removeExif() {
      if (!originalImg) return;
      const W = originalImg.naturalWidth;
      const H = originalImg.naturalHeight;
      const canvas = ImageUtils.createCanvas(W, H);
      const ctx = canvas.getContext('2d');
      ctx.drawImage(originalImg, 0, 0);

      const blob = await ImageUtils.canvasToBlob(canvas, 'image/png');
      if (prevBlobUrl) { try { URL.revokeObjectURL(prevBlobUrl); } catch(e) {} }
      const url = URL.createObjectURL(blob);
      prevBlobUrl = url;
      resultBlob = blob;
      resultImg.src = url;
      return blob;
    }

    applyBtn.addEventListener('click', async function() {
      if (!originalImg) return;
      applyBtn.disabled = true;
      applyBtn.textContent = '🔄 Removing...';
      status.innerHTML = '<div class="spinner"></div>';
      try {
        await removeExif();
        exifInfo.innerHTML = '<span class="exif-clear">✅ EXIF metadata successfully removed! The image is now clean.</span>';
        status.textContent = 'Done! Click Download to save the clean image.';
        downloadBtn.classList.remove('hidden');
      } catch (err) {
        status.textContent = 'Error: ' + err.message;
      } finally {
        applyBtn.disabled = false;
        applyBtn.textContent = '🗑️ Remove EXIF';
      }
    });

    downloadBtn.addEventListener('click', function() {
      if (resultBlob) {
        const base = (currentFile.name || 'image').replace(/\.[^.]+$/, '');
        ImageUtils.download(resultBlob, base + '-clean.png');
        try { SmartImgNextStep.show(); } catch(e) {}
      }
    });

    resetBtn.addEventListener('click', function() {
      if (prevBlobUrl) { try { URL.revokeObjectURL(prevBlobUrl); } catch(e) {} }
      prevBlobUrl = null;
      currentFile = null;
      originalImg = null;
      resultBlob = null;
      previewArea.classList.remove('active');
      const bp = document.getElementById('beforeAfterPreview');
      if (bp) bp.classList.remove('hidden');
      dropzone.classList.remove('hidden');
      fileInput.value = '';
      status.textContent = '';
      downloadBtn.classList.add('hidden');
      resultImg.src = '';
      exifStatus.style.display = 'none';
      exifInfo.textContent = '';
    });

    (function() {
      var _handleFile = typeof handleFile === 'function' ? handleFile : null;
      if (_handleFile) {
        window.initSampleButton('https://images.unsplash.com/photo-1506744038136-46273834b3fb?w=800&q=80', _handleFile);
      }
    })();

