const dropzone = document.getElementById('dropzone');
    const fileInput = document.getElementById('fileInput');
    const previewArea = document.getElementById('previewArea');
    const resultImg = document.getElementById('resultImg');
    const effectSelect = document.getElementById('effectSelect');
    const applyBtn = document.getElementById('applyBtn');
    const downloadBtn = document.getElementById('downloadBtn');
    const resetBtn = document.getElementById('resetBtn');
    const status = document.getElementById('status');

    let currentFile = null;
    let originalImg = null;
    let resultBlob = null;
    let prevBlobUrl = null;

    setupDropzone({ dropzoneId: 'dropzone', inputId: 'fileInput', onFile: handleFile });

    function handleFile(file) {
      if (!file.type.startsWith('image/')) { status.textContent = 'Please select an image file.'; return; }
      currentFile = file;
      ImageUtils.load(file).then(async img => {
        originalImg = img;
        status.innerHTML = '<div class="spinner"></div>';
        try {
          await applyEffect();
        } catch(e) {
          status.textContent = 'Error: ' + e.message;
          return;
        }
        previewArea.classList.add('active');
        const bp = document.getElementById('beforeAfterPreview');
        if (bp) bp.classList.add('hidden');
        dropzone.classList.add('hidden');
        status.textContent = '';
        downloadBtn.classList.remove('hidden');
      }).catch(err => {
        status.textContent = 'Error loading image: ' + err.message;
      });
    }

    async function applyEffect() {
      if (!originalImg) return;
      const W = originalImg.naturalWidth;
      const H = originalImg.naturalHeight;
      const effect = effectSelect.value;

      const canvas = ImageUtils.createCanvas(W, H);
      const ctx = canvas.getContext('2d');
      ctx.drawImage(originalImg, 0, 0);

      const imgData = ctx.getImageData(0, 0, W, H);
      const d = imgData.data;

      if (effect === 'grayscale') {
        for (let i = 0; i < d.length; i += 4) {
          const gray = Math.round(d[i]*0.299 + d[i+1]*0.587 + d[i+2]*0.114);
          d[i] = d[i+1] = d[i+2] = gray;
        }
        ctx.putImageData(imgData, 0, 0);
      } else if (effect === 'sepia') {
        for (let i = 0; i < d.length; i += 4) {
          const r = d[i], g = d[i+1], b = d[i+2];
          d[i]   = Math.min(255, r*0.393 + g*0.769 + b*0.189);
          d[i+1] = Math.min(255, r*0.349 + g*0.686 + b*0.168);
          d[i+2] = Math.min(255, r*0.272 + g*0.534 + b*0.131);
        }
        ctx.putImageData(imgData, 0, 0);
      } else if (effect === 'invert') {
        for (let i = 0; i < d.length; i += 4) {
          d[i]   = 255 - d[i];
          d[i+1] = 255 - d[i+1];
          d[i+2] = 255 - d[i+2];
        }
        ctx.putImageData(imgData, 0, 0);
      } else if (effect === 'posterize') {
        const levels = 4;
        const step = 255 / (levels - 1);
        for (let i = 0; i < d.length; i += 4) {
          d[i]   = Math.round(Math.round(d[i]   / step) * step);
          d[i+1] = Math.round(Math.round(d[i+1] / step) * step);
          d[i+2] = Math.round(Math.round(d[i+2] / step) * step);
        }
        ctx.putImageData(imgData, 0, 0);
      } else if (effect === 'blur') {
        // Simple box blur using CSS filter as a shortcut
        // Re-draw with filter
        const tmpCanvas = ImageUtils.createCanvas(W, H);
        const tmpCtx = tmpCanvas.getContext('2d');
        tmpCtx.filter = 'blur(4px)';
        tmpCtx.drawImage(originalImg, 0, 0);
        ctx.clearRect(0, 0, W, H);
        ctx.drawImage(tmpCanvas, 0, 0);
      } else if (effect === 'sharpen') {
        // Unsharp mask: blur then blend
        const tmpCanvas = ImageUtils.createCanvas(W, H);
        const tmpCtx = tmpCanvas.getContext('2d');
        tmpCtx.filter = 'blur(1px)';
        tmpCtx.drawImage(originalImg, 0, 0);
        const blurData = tmpCtx.getImageData(0, 0, W, H).data;
        for (let i = 0; i < d.length; i += 4) {
          d[i]   = Math.min(255, Math.max(0, d[i]   + (d[i]   - blurData[i])   * 0.8));
          d[i+1] = Math.min(255, Math.max(0, d[i+1] + (d[i+1] - blurData[i+1]) * 0.8));
          d[i+2] = Math.min(255, Math.max(0, d[i+2] + (d[i+2] - blurData[i+2]) * 0.8));
        }
        ctx.putImageData(imgData, 0, 0);
      }

      const blob = await ImageUtils.canvasToBlob(canvas, 'image/png');
      if (prevBlobUrl) { try { URL.revokeObjectURL(prevBlobUrl); } catch(e) {} }
      const url = URL.createObjectURL(blob);
      prevBlobUrl = url;
      resultBlob = blob;
      resultImg.src = url;
      return blob;
    }

    applyBtn.addEventListener('click', async function() {
      if (!originalImg) return;
      applyBtn.disabled = true;
      applyBtn.textContent = '🔄 Applying...';
      status.innerHTML = '<div class="spinner"></div>';
      try {
        await applyEffect();
        status.textContent = 'Done! Click Download to save.';
      } catch (err) {
        status.textContent = 'Error: ' + err.message;
      } finally {
        applyBtn.disabled = false;
        applyBtn.textContent = '✨ Apply Effect';
      }
    });

    downloadBtn.addEventListener('click', function() {
      if (resultBlob) {
        const base = (currentFile.name || 'image').replace(/\.[^.]+$/, '');
        ImageUtils.download(resultBlob, base + '-effect.png');
        try { SmartImgNextStep.show(); } catch(e) {}
      }
    });

    resetBtn.addEventListener('click', function() {
      if (prevBlobUrl) { try { URL.revokeObjectURL(prevBlobUrl); } catch(e) {} }
      prevBlobUrl = null;
      currentFile = null;
      originalImg = null;
      resultBlob = null;
      previewArea.classList.remove('active');
      const bp = document.getElementById('beforeAfterPreview');
      if (bp) bp.classList.remove('hidden');
      dropzone.classList.remove('hidden');
      fileInput.value = '';
      status.textContent = '';
      downloadBtn.classList.add('hidden');
      resultImg.src = '';
      effectSelect.value = 'grayscale';
    });

    (function() {
      var _handleFile = typeof handleFile === 'function' ? handleFile : null;
      if (_handleFile) {
        window.initSampleButton('https://images.unsplash.com/photo-1506744038136-46273834b3fb?w=800&q=80', _handleFile);
      }
    })();

