const dropzone = document.getElementById('dropzone');
    const fileInput = document.getElementById('fileInput');
    const previewArea = document.getElementById('previewArea');
    const resultImg = document.getElementById('resultImg');
    const offsetXRange = document.getElementById('offsetXRange');
    const offsetYRange = document.getElementById('offsetYRange');
    const blurRange = document.getElementById('blurRange');
    const shadowColorPicker = document.getElementById('shadowColorPicker');
    const bgColorPicker = document.getElementById('bgColorPicker');
    const offsetXVal = document.getElementById('offsetXVal');
    const offsetYVal = document.getElementById('offsetYVal');
    const blurVal = document.getElementById('blurVal');
    const shadowColorHex = document.getElementById('shadowColorHex');
    const bgColorHex = document.getElementById('bgColorHex');
    const customBgRow = document.getElementById('customBgRow');
    const applyBtn = document.getElementById('applyBtn');
    const downloadBtn = document.getElementById('downloadBtn');
    const resetBtn = document.getElementById('resetBtn');
    const status = document.getElementById('status');

    let currentFile = null;
    let originalImg = null;
    let resultBlob = null;
    let prevBlobUrl = null;
    let bgType = 'white';

    setupDropzone({ dropzoneId: 'dropzone', inputId: 'fileInput', onFile: handleFile });

    offsetXRange.addEventListener('input', () => { offsetXVal.textContent = offsetXRange.value + 'px'; });
    offsetYRange.addEventListener('input', () => { offsetYVal.textContent = offsetYRange.value + 'px'; });
    blurRange.addEventListener('input', () => { blurVal.textContent = blurRange.value + 'px'; });
    shadowColorPicker.addEventListener('input', () => { shadowColorHex.textContent = shadowColorPicker.value; });
    bgColorPicker.addEventListener('input', () => { bgColorHex.textContent = bgColorPicker.value; });

    document.querySelectorAll('.bg-option').forEach(btn => {
      btn.addEventListener('click', function() {
        document.querySelectorAll('.bg-option').forEach(b => b.classList.remove('active'));
        this.classList.add('active');
        bgType = this.getAttribute('data-bg');
        customBgRow.style.display = bgType === 'custom' ? 'flex' : 'none';
      });
    });

    function handleFile(file) {
      if (!file.type.startsWith('image/')) { status.textContent = 'Please select an image file.'; return; }
      currentFile = file;
      ImageUtils.load(file).then(async img => {
        originalImg = img;
        status.innerHTML = '<div class="spinner"></div>';
        try {
          await applyShadow();
        } catch(e) {
          status.textContent = 'Error: ' + e.message;
          return;
        }
        previewArea.classList.add('active');
        const bp = document.getElementById('beforeAfterPreview');
        if (bp) bp.classList.add('hidden');
        dropzone.classList.add('hidden');
        status.textContent = '';
        downloadBtn.classList.remove('hidden');
      }).catch(err => {
        status.textContent = 'Error loading image: ' + err.message;
      });
    }

    async function applyShadow() {
      if (!originalImg) return;
      const W = originalImg.naturalWidth;
      const H = originalImg.naturalHeight;
      const offX = parseInt(offsetXRange.value);
      const offY = parseInt(offsetYRange.value);
      const blurPx = parseInt(blurRange.value);
      const shadowColor = shadowColorPicker.value;

      // Determine background color
      let bgColor = '#ffffff';
      if (bgType === 'transparent') { bgColor = null; }
      else if (bgType === 'custom') { bgColor = bgColorPicker.value; }

      // Canvas size: expand to fit shadow
      const pad = blurPx * 2 + Math.max(Math.abs(offX), Math.abs(offY));
      const cw = W + pad * 2;
      const ch = H + pad * 2;
      const dx = pad;
      const dy = pad;

      const canvas = ImageUtils.createCanvas(cw, ch);
      const ctx = canvas.getContext('2d');

      // Fill background
      if (bgColor) {
        ctx.fillStyle = bgColor;
        ctx.fillRect(0, 0, cw, ch);
      }

      // Draw image with shadow
      ctx.shadowColor = shadowColor;
      ctx.shadowBlur = blurPx;
      ctx.shadowOffsetX = offX;
      ctx.shadowOffsetY = offY;
      ctx.drawImage(originalImg, dx, dy, W, H);

      const blob = await ImageUtils.canvasToBlob(canvas, 'image/png');
      if (prevBlobUrl) { try { URL.revokeObjectURL(prevBlobUrl); } catch(e) {} }
      const url = URL.createObjectURL(blob);
      prevBlobUrl = url;
      resultBlob = blob;
      resultImg.src = url;
      return blob;
    }

    applyBtn.addEventListener('click', async function() {
      if (!originalImg) return;
      applyBtn.disabled = true;
      applyBtn.textContent = '🔄 Applying...';
      status.innerHTML = '<div class="spinner"></div>';
      try {
        await applyShadow();
        status.textContent = 'Done! Click Download to save.';
      } catch (err) {
        status.textContent = 'Error: ' + err.message;
      } finally {
        applyBtn.disabled = false;
        applyBtn.textContent = '✨ Apply Shadow';
      }
    });

    downloadBtn.addEventListener('click', function() {
      if (resultBlob) {
        const base = (currentFile.name || 'image').replace(/\.[^.]+$/, '');
        ImageUtils.download(resultBlob, base + '-shadow.png');
        try { SmartImgNextStep.show(); } catch(e) {}
      }
    });

    resetBtn.addEventListener('click', function() {
      if (prevBlobUrl) { try { URL.revokeObjectURL(prevBlobUrl); } catch(e) {} }
      prevBlobUrl = null;
      currentFile = null;
      originalImg = null;
      resultBlob = null;
      previewArea.classList.remove('active');
      const bp = document.getElementById('beforeAfterPreview');
      if (bp) bp.classList.remove('hidden');
      dropzone.classList.remove('hidden');
      fileInput.value = '';
      status.textContent = '';
      downloadBtn.classList.add('hidden');
      resultImg.src = '';
      offsetXRange.value = 8;
      offsetYRange.value = 8;
      blurRange.value = 12;
      offsetXVal.textContent = '8px';
      offsetYVal.textContent = '8px';
      blurVal.textContent = '12px';
      shadowColorPicker.value = '#000000';
      shadowColorHex.textContent = '#000000';
      bgType = 'white';
      document.querySelectorAll('.bg-option').forEach(b => b.classList.remove('active'));
      document.querySelector('.bg-option[data-bg="white"]').classList.add('active');
      customBgRow.style.display = 'none';
    });

    (function() {
      var _handleFile = typeof handleFile === 'function' ? handleFile : null;
      if (_handleFile) {
        window.initSampleButton('https://images.unsplash.com/photo-1506744038136-46273834b3fb?w=800&q=80', _handleFile);
      }
    })();

