const dropzone = document.getElementById('dropzone');
    const fileInput = document.getElementById('fileInput');
    const previewArea = document.getElementById('previewArea');
    const splitResults = document.getElementById('splitResults');
    const applyBtn = document.getElementById('applyBtn');
    const downloadAllBtn = document.getElementById('downloadAllBtn');
    const resetBtn = document.getElementById('resetBtn');
    const status = document.getElementById('status');

    let currentFile = null;
    let originalImg = null;
    let gridType = '2x2';
    let pieceBlobs = []; // {blob, name}

    setupDropzone({ dropzoneId: 'dropzone', inputId: 'fileInput', onFile: handleFile });

    document.querySelectorAll('.grid-option').forEach(btn => {
      btn.addEventListener('click', function() {
        document.querySelectorAll('.grid-option').forEach(b => b.classList.remove('active'));
        this.classList.add('active');
        gridType = this.getAttribute('data-grid');
      });
    });
    // default active
    document.querySelector('.grid-option[data-grid="2x2"]').classList.add('active');

    function handleFile(file) {
      if (!file.type.startsWith('image/')) { status.textContent = 'Please select an image file.'; return; }
      currentFile = file;
      ImageUtils.load(file).then(img => {
        originalImg = img;
        status.textContent = 'Image loaded. Click "Split Image" to continue.';
        previewArea.classList.add('active');
        const bp = document.getElementById('beforeAfterPreview');
        if (bp) bp.classList.add('hidden');
        dropzone.classList.add('hidden');
        splitResults.innerHTML = '';
        downloadAllBtn.classList.add('hidden');
      }).catch(err => {
        status.textContent = 'Error loading image: ' + err.message;
      });
    }

    async function splitImage() {
      if (!originalImg) return;
      const W = originalImg.naturalWidth;
      const H = originalImg.naturalHeight;
      const [cols, rows] = gridType.split('x').map(Number);
      const pw = Math.floor(W / cols);
      const ph = Math.floor(H / rows);

      pieceBlobs = [];
      splitResults.innerHTML = '';
      splitResults.style.display = 'grid';
      splitResults.style.gridTemplateColumns = 'repeat(' + cols + ', 1fr)';
      splitResults.style.gap = '8px';

      for (let r = 0; r < rows; r++) {
        for (let c = 0; c < cols; c++) {
          const sx = c * pw;
          const sy = r * ph;
          const sw = (c === cols - 1) ? W - sx : pw;
          const sh = (r === rows - 1) ? H - sy : ph;

          const canvas = ImageUtils.createCanvas(sw, sh);
          const ctx = canvas.getContext('2d');
          ctx.drawImage(originalImg, sx, sy, sw, sh, 0, 0, sw, sh);

          const blob = await ImageUtils.canvasToBlob(canvas, 'image/png');
          const name = (currentFile.name || 'image').replace(/\.[^.]+$/, '') + '_' + (r+1) + '_' + (c+1) + '.png';
          pieceBlobs.push({ blob, name });

          const pieceDiv = document.createElement('div');
          pieceDiv.className = 'split-piece';
          const img = document.createElement('img');
          img.src = URL.createObjectURL(blob);
          const dlBtn = document.createElement('button');
          dlBtn.className = 'btn btn-secondary';
          dlBtn.style.fontSize = '.8rem';
          dlBtn.style.padding = '4px 8px';
          dlBtn.textContent = '⬇️ ' + name;
          dlBtn.onclick = function() { ImageUtils.download(blob, name); };
          pieceDiv.appendChild(img);
          pieceDiv.appendChild(dlBtn);
          splitResults.appendChild(pieceDiv);
        }
      }
    }

    applyBtn.addEventListener('click', async function() {
      if (!originalImg) { status.textContent = 'Please upload an image first.'; return; }
      applyBtn.disabled = true;
      applyBtn.textContent = '🔄 Splitting...';
      status.innerHTML = '<div class="spinner"></div>';
      try {
        await splitImage();
        status.textContent = 'Done! Download pieces below or all as ZIP.';
        downloadAllBtn.classList.remove('hidden');
      } catch (err) {
        status.textContent = 'Error: ' + err.message;
      } finally {
        applyBtn.disabled = false;
        applyBtn.textContent = '✨ Split Image';
      }
    });

    downloadAllBtn.addEventListener('click', async function() {
      if (typeof JSZip === 'undefined') { status.textContent = 'JSZip not loaded. Please try again.'; return; }
      status.innerHTML = '<div class="spinner"></div> Downloading ZIP...';
      try {
        const zip = new JSZip();
        pieceBlobs.forEach(p => { zip.file(p.name, p.blob); });
        const content = await zip.generateAsync({ type: 'blob' });
        const url = URL.createObjectURL(content);
        const a = document.createElement('a');
        a.href = url;
        a.download = (currentFile.name || 'image').replace(/\.[^.]+$/, '') + '_split.zip';
        a.click();
        setTimeout(() => URL.revokeObjectURL(url), 1000);
        status.textContent = 'ZIP downloaded!';
      } catch (err) {
        status.textContent = 'Error creating ZIP: ' + err.message;
      }
    });

    resetBtn.addEventListener('click', function() {
      currentFile = null;
      originalImg = null;
      pieceBlobs = [];
      previewArea.classList.remove('active');
      const bp = document.getElementById('beforeAfterPreview');
      if (bp) bp.classList.remove('hidden');
      dropzone.classList.remove('hidden');
      fileInput.value = '';
      status.textContent = '';
      downloadAllBtn.classList.add('hidden');
      splitResults.innerHTML = '';
    });

    (function() {
      var _handleFile = typeof handleFile === 'function' ? handleFile : null;
      if (_handleFile) {
        window.initSampleButton('https://images.unsplash.com/photo-1506744038136-46273834b3fb?w=800&q=80', _handleFile);
      }
    })();

