tools.inline_js:
(function() {
  'use strict';

  const $ = function(id) { return document.getElementById(id); };

  // Tab switching
  const tabs = document.querySelectorAll('.qr-tab');
  const panes = document.querySelectorAll('.qr-tab-pane');
  let currentTab = 'url';
  tabs.forEach(function(btn) {
    btn.addEventListener('click', function() {
      currentTab = btn.dataset.tab;
      tabs.forEach(function(b) { b.classList.toggle('active', b === btn); });
      panes.forEach(function(p) { p.classList.toggle('active', p.dataset.pane === currentTab); });
    });
  });

  // Inputs
  const urlInput = $('urlInput');
  const textInput = $('textInput');
  const wifiSsid = $('wifiSsid');
  const wifiPassword = $('wifiPassword');
  const wifiType = $('wifiType');
  const wifiHidden = $('wifiHidden');
  const vcName = $('vcName');
  const vcOrg = $('vcOrg');
  const vcTel = $('vcTel');
  const vcEmail = $('vcEmail');
  const vcUrl = $('vcUrl');
  const emTo = $('emTo');
  const emSubj = $('emSubj');
  const emBody = $('emBody');

  // Color/size/EC
  const fgColor = $('fgColor');
  const bgColor = $('bgColor');
  const fgColorTxt = $('fgColorTxt');
  const bgColorTxt = $('bgColorTxt');
  const ecLevel = $('ecLevel');
  const qrSize = $('qrSize');
  const qrSizeVal = $('qrSizeVal');
  const logoInput = $('logoInput');
  const logoPreview = $('logoPreview');
  const logoSize = $('logoSize');
  const logoSizeVal = $('logoSizeVal');

  fgColor.addEventListener('input', function() { fgColorTxt.value = fgColor.value; });
  fgColorTxt.addEventListener('input', function() { if (/^#[0-9a-fA-F]{6}$/.test(fgColorTxt.value)) fgColor.value = fgColorTxt.value; });
  bgColor.addEventListener('input', function() { bgColorTxt.value = bgColor.value; });
  bgColorTxt.addEventListener('input', function() { if (/^#[0-9a-fA-F]{6}$/.test(bgColorTxt.value)) bgColor.value = bgColorTxt.value; });
  qrSize.addEventListener('input', function() { qrSizeVal.textContent = qrSize.value; });
  logoSize.addEventListener('input', function() { logoSizeVal.textContent = logoSize.value + '%'; });

  let logoImage = null;
  logoInput.addEventListener('change', function() {
    if (!logoInput.files[0]) return;
    const reader = new FileReader();
    reader.onload = function(e) {
      const img = new Image();
      img.onload = function() {
        logoImage = img;
        logoPreview.style.backgroundImage = 'url(' + e.target.result + ')';
        logoPreview.textContent = '';
      };
      img.src = e.target.result;
    };
    reader.readAsDataURL(logoInput.files[0]);
  });

  // Canvas and info
  const canvas = $('qrCanvas');
  const qrModules = $('qrModules');
  const qrLen = $('qrLen');
  const qrOutSize = $('qrOutSize');
  const dlPngBtn = $('dlPngBtn');
  const dlSvgBtn = $('dlSvgBtn');
  const addBatchBtn = $('addBatchBtn');

  function getPayload() {
    if (currentTab === 'url') return (urlInput.value || '').trim();
    if (currentTab === 'text') return (textInput.value || '').trim();
    if (currentTab === 'wifi') {
      var ssid = (wifiSsid.value || '').trim();
      if (!ssid) return '';
      var sec = (wifiType.value || 'WPA');
      var pwd = (wifiPassword.value || '');
      var hidden = wifiHidden && wifiHidden.checked ? 'true' : 'false';
      return 'WIFI:T:' + sec + ';S:' + ssid + ';P:' + pwd + ';H:' + hidden + ';;';
    }
    if (currentTab === 'vcard') {
      var name = (vcName.value || '').trim();
      if (!name) return '';
      return 'BEGIN:VCARD\nVERSION:3.0\nFN:' + name + '\nORG:' + (vcOrg.value || '') + '\nTEL:' + (vcTel.value || '') + '\nEMAIL:' + (vcEmail.value || '') + '\nURL:' + (vcUrl.value || '') + '\nEND:VCARD';
    }
    if (currentTab === 'email') {
      var to = (emTo.value || '').trim();
      if (!to) return '';
      var mailto = 'mailto:' + to;
      var params = [];
      if (emSubj.value) params.push('subject=' + encodeURIComponent(emSubj.value));
      if (emBody.value) params.push('body=' + encodeURIComponent(emBody.value));
      if (params.length) mailto += '?' + params.join('&');
      return mailto;
    }
    return '';
  }

  function makeQR(payload) {
    const ec = (ecLevel.value || 'M');
    const qr = qrcode(0, ec);
    qr.addData(payload);
    qr.make();
    return qr;
  }

  function drawQRToCanvas(qr, targetCanvas, size) {
    targetCanvas.width = size;
    targetCanvas.height = size;
    const moduleCount = qr.getModuleCount();
    const cellSize = size / moduleCount;
    const ctx = targetCanvas.getContext('2d');
    ctx.fillStyle = bgColor.value;
    ctx.fillRect(0, 0, size, size);
    ctx.fillStyle = fgColor.value;
    for (let r = 0; r < moduleCount; r++) {
      for (let c = 0; c < moduleCount; c++) {
        if (qr.isDark(r, c)) ctx.fillRect(c * cellSize, r * cellSize, cellSize, cellSize);
      }
    }
    if (logoImage) {
      const pct = parseInt(logoSize.value) || 20;
      const logoW = size * pct / 100;
      const logoH = logoW * (logoImage.naturalHeight / logoImage.naturalWidth);
      const x = (size - logoW) / 2;
      const y = (size - logoH) / 2;
      ctx.fillStyle = '#fff';
      const pad = logoW * 0.08;
      ctx.fillRect(x - pad, y - pad, logoW + pad * 2, logoH + pad * 2);
      ctx.drawImage(logoImage, x, y, logoW, logoH);
    }
    return moduleCount;
  }

  function generate() {
    const payload = getPayload();
    if (!payload) { alert('Please enter content.'); return null; }
    const size = parseInt(qrSize.value) || 512;
    const qr = makeQR(payload);
    const moduleCount = drawQRToCanvas(qr, canvas, size);
    qrModules.textContent = moduleCount + 'x' + moduleCount;
    qrLen.textContent = payload.length;
    qrOutSize.textContent = size + 'x' + size + ' px';
    return qr;
  }

  dlPngBtn.addEventListener('click', function() {
    const qr = generate();
    if (!qr) return;
    canvas.toBlob(function(blob) {
      const a = document.createElement('a');
      a.href = URL.createObjectURL(blob);
      a.download = 'qrcode-' + Date.now() + '.png';
      a.click();
      setTimeout(function() { URL.revokeObjectURL(a.href); }, 1000);
    });
  });

  dlSvgBtn.addEventListener('click', function() {
    const payload = getPayload();
    if (!payload) { alert('Please enter content.'); return; }
    const qr = makeQR(payload);
    const moduleCount = qr.getModuleCount();
    let svg = '<svg xmlns="http://www.w3.org/2000/svg" width="512" height="512" viewBox="0 0 ' + moduleCount + ' ' + moduleCount + '">';
    svg += '<rect width="100%" height="100%" fill="' + bgColor.value + '"/>';
    for (let r = 0; r < moduleCount; r++) {
      for (let c = 0; c < moduleCount; c++) {
        if (qr.isDark(r, c)) svg += '<rect x="' + c + '" y="' + r + '" width="1" height="1" fill="' + fgColor.value + '"/>';
      }
    }
    svg += '</svg>';
    const blob = new Blob([svg], { type: 'image/svg+xml' });
    const a = document.createElement('a');
    a.href = URL.createObjectURL(blob);
    a.download = 'qrcode-' + Date.now() + '.svg';
    a.click();
    setTimeout(function() { URL.revokeObjectURL(a.href); }, 1000);
  });

  // ===== Batch multi-row input =====
  const batchRows = $('batchRows');
  const addRowBtn = $('addRowBtn');
  const clearBatchBtn = $('clearBatchBtn');
  const batchCount = $('batchCount');
  const genBatchBtn = $('genBatchBtn');
  const batchPreview = $('batchPreview');

  function addBatchRow(value) {
    const div = document.createElement('div');
    div.className = 'qr-batch-row';
    const idx = batchRows.children.length + 1;
    const safe = (value || '').replace(/"/g, '&quot;');
    div.innerHTML = '<span class="qr-row-num">' + idx + '.</span><input type="text" placeholder="https://example.com" value="' + safe + '"><button title="Remove">✕</button>';
    div.querySelector('button').addEventListener('click', function() {
      div.remove();
      renumberRows();
    });
    batchRows.appendChild(div);
    renumberRows();
  }

  function renumberRows() {
    const rows = batchRows.querySelectorAll('.qr-batch-row');
    rows.forEach(function(r, i) {
      r.querySelector('.qr-row-num').textContent = (i + 1) + '.';
    });
    batchCount.textContent = rows.length;
  }

  function readBatchRows() {
    const inputs = batchRows.querySelectorAll('input[type="text"]');
    const out = [];
    inputs.forEach(function(inp) {
      const v = (inp.value || '').trim();
      if (v) out.push(v);
    });
    return out;
  }

  addRowBtn.addEventListener('click', function() { addBatchRow(''); });
  addBatchBtn.addEventListener('click', function() {
    const val = getPayload();
    if (val) addBatchRow(val);
  });
  clearBatchBtn.addEventListener('click', function() {
    batchRows.innerHTML = '';
    renumberRows();
    batchPreview.innerHTML = '';
  });

  addBatchRow('https://smartimgkit.com');
  addBatchRow('https://github.com');
  addBatchRow('https://example.com');

  genBatchBtn.addEventListener('click', async function() {
    const rows = readBatchRows();
    if (!rows.length) { alert('Please enter at least one URL or text in the batch rows.'); return; }
    genBatchBtn.disabled = true;
    genBatchBtn.textContent = '⏳ Generating ' + rows.length + ' QR codes...';
    batchPreview.innerHTML = '';
    const size = 256;
    const zip = new JSZip();
    const usedNames = {};
    try {
      for (let i = 0; i < rows.length; i++) {
        const payload = rows[i];
        const qr = makeQR(payload);
        const tmpCanvas = document.createElement('canvas');
        drawQRToCanvas(qr, tmpCanvas, size);
        const blob = await new Promise(function(res) { tmpCanvas.toBlob(res); });
        let name = payload.replace(/^https?:\/\//, '').replace(/[\/?&=:#%]/g, '_').slice(0, 40) || ('qr-' + (i + 1));
        if (usedNames[name]) {
          let suffix = 2;
          while (usedNames[name + '-' + suffix]) suffix++;
          name = name + '-' + suffix;
        }
        usedNames[name] = true;
        zip.file(name + '.png', blob);
        const wrap = document.createElement('div');
        wrap.innerHTML = '<img src="' + tmpCanvas.toDataURL() + '"><div style="overflow:hidden;text-overflow:ellipsis;white-space:nowrap;margin-top:2px;">' + name + '</div>';
        batchPreview.appendChild(wrap);
      }
      genBatchBtn.textContent = '⏳ Creating ZIP...';
      const zipBlob = await zip.generateAsync({ type: 'blob' });
      const a = document.createElement('a');
      a.download = 'qr-batch-' + Date.now() + '.zip';
      a.href = URL.createObjectURL(zipBlob);
      a.click();
      setTimeout(function() { URL.revokeObjectURL(a.href); }, 1000);
      genBatchBtn.textContent = '✅ Done! ' + rows.length + ' codes generated.';
      setTimeout(function() { genBatchBtn.textContent = '✨ Generate Batch (multi-URL → ZIP)'; genBatchBtn.disabled = false; }, 3000);
    } catch (err) {
      genBatchBtn.textContent = '❌ Error: ' + err.message;
      genBatchBtn.disabled = false;
      console.error(err);
    }
  });
})();

const dropzone = document.getElementById('dropzone');
    const fileInput = document.getElementById('fileInput');
    const previewArea = document.getElementById('previewArea');
    const previewImg = document.getElementById('previewImg');
    const keepRatio = document.getElementById('keepRatio');
    const widthInput = document.getElementById('widthInput');
    const heightInput = document.getElementById('heightInput');
    const pctRange = document.getElementById('pctRange');
    const pctVal = document.getElementById('pctVal');
    const resizeBtn = document.getElementById('resizeBtn');
    const downloadBtn = document.getElementById('downloadBtn');
    const resetBtn = document.getElementById('resetBtn');
    const status = document.getElementById('status');

    let currentFile = null, origW = 0, origH = 0, resultBlob = null;

    setupDropzone({ dropzoneId: 'dropzone', inputId: 'fileInput', onFile: handleFile });

    function handleFile(file) {
      if (!file.type.startsWith('image/')) { status.textContent = 'Please select an image file.'; return; }
      currentFile = file;
      ImageUtils.load(file).then(img => {
        origW = img.naturalWidth; origH = img.naturalHeight;
        previewImg.src = img.src;
        widthInput.value = origW; heightInput.value = origH;
        pctRange.value = 100; pctVal.textContent = '100%';
        previewArea.classList.add('active');
          document.getElementById('beforeAfterPreview') && document.getElementById('beforeAfterPreview').classList.add('hidden');
        dropzone.classList.add('hidden');
        status.textContent = '';
        downloadBtn.classList.add('hidden');
      });
    }

    keepRatio.addEventListener('change', () => {
      if (keepRatio.checked && origW) { heightInput.value = Math.round(parseInt(widthInput.value||0) * (origH/origW)); }
    });
    widthInput.addEventListener('input', () => {
      if (keepRatio.checked && origW) { heightInput.value = Math.round(parseInt(widthInput.value||0) * (origH/origW)); }
    });
    heightInput.addEventListener('input', () => {
      if (keepRatio.checked && origH) { widthInput.value = Math.round(parseInt(heightInput.value||0) * (origW/origH)); }
    });
    pctRange.addEventListener('input', () => {
      pctVal.textContent = pctRange.value + '%';
      if (origW) { widthInput.value = Math.round(origW * pctRange.value / 100); heightInput.value = Math.round(origH * pctRange.value / 100); }
    });

    resizeBtn.addEventListener('click', async () => {
      if (!currentFile) return;
      const w = parseInt(widthInput.value) || origW;
      const h = parseInt(heightInput.value) || origH;
      resizeBtn.disabled = true;
      resizeBtn.textContent = '🔄 Resizing...';
      status.innerHTML = '<div class="spinner"></div>';
      try {
        const img = await ImageUtils.load(currentFile);
        const canvas = ImageUtils.createCanvas(w, h);
        canvas.getContext('2d').drawImage(img, 0, 0, w, h);
        const blob = await ImageUtils.canvasToBlob(canvas, currentFile.type, 0.92);
        resultBlob = blob;
        previewImg.src = canvas.toDataURL();
        downloadBtn.classList.remove('hidden');
        status.textContent = 'Resized to ' + w + '×' + h;
      } catch (err) {
        status.textContent = 'Error: ' + err.message;
      } finally {
        resizeBtn.disabled = false;
        resizeBtn.textContent = '📐 Resize';
      }
    });

    downloadBtn.addEventListener('click', () => {
      if (resultBlob) {
        const ext = currentFile.name.split('.').pop();
        const base = currentFile.name.replace(/\.[^.]+$/, '');
        ImageUtils.download(resultBlob, base + '-resized.' + ext);
      }
    });

    resetBtn.addEventListener('click', () => {
      currentFile = null; resultBlob = null; origW = 0; origH = 0;
      previewArea.classList.remove('active');
          document.getElementById('beforeAfterPreview') && document.getElementById('beforeAfterPreview').classList.remove('hidden');
      dropzone.classList.remove('hidden');
      fileInput.value = ''; status.textContent = '';
      downloadBtn.classList.add('hidden');
    });

  // Sample image & Next Step
  (function() {
    var _handleFile = typeof handleFile === 'function' ? handleFile : null;
    if (_handleFile) {
      window.initSampleButton('https://images.unsplash.com/photo-1441974231531-c6227db76b6e?w=800&q=80', _handleFile);
    }
    // Show next-step on download click
    var dlBtn = document.getElementById('downloadBtn') || document.querySelector('.btn-primary[onclick*="download"], .btn-secondary[onclick*="download"]');
    if (dlBtn) {
      dlBtn.addEventListener('click', function() { SmartImgNextStep.show(); });
    }
  })();

